import { ChangeDetectionStrategy, Component, Input, effect } from '@angular/core';

import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { TranslationService } from '../../../core/services/translation.service';

interface TitlePart {
	text: string;
	style?: 'medium' | 'light' | 'barcely';
	break?: boolean | string;
}

@Component({
	selector: 'app-service-audit',
	standalone: true,
	imports: [CommonModule, RouterModule, TranslateModule],
	templateUrl: './service-audit.component.html',
	styleUrl: './service-audit.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ServiceAuditComponent {
	@Input() sectionKey = 'SERVICEAUDIT.BRANDING';
	@Input() consultationLink = '/contact';

	constructor(
		public translationService: TranslationService,
		private translate: TranslateService,
	) {
		effect(() => {
			this.translationService.currentLang();
		});
	}

	getTitleParts(): TitlePart[] {
		const parts = this.translate.instant(this.sectionKey + '.TITLE_PARTS');

		return Array.isArray(parts) ? parts : [];
	}

	getDescriptions(): string[] {
		const list = this.translate.instant(this.sectionKey + '.DESCRIPTIONS');

		return Array.isArray(list) ? list : [];
	}
}
